from geometry import *
import json,time
base=json.load(open(ROOT+'/paths.json'))
# Optimize centreline control points only, never letter-area fill paths.
for prefix,box in [('u',(340,450,424,570)),('n',(421,450,500,570)),('p',(496,450,567,623)),('i',(567,420,610,570))]:
 names=[k for k in base if k.startswith(prefix+'_')]
 sub={k:np.array(base[k]) for k in names}
 # Shared endpoints remain shared while fitting.
 nodes=[];indices={}
 for k in names:
  ids=[]
  for v in sub[k]:
   match=next((j for j,a in enumerate(nodes) if np.linalg.norm(v-a)<.01),None)
   if match is None:match=len(nodes);nodes.append(v)
   ids.append(match)
  indices[k]=ids
 orig=np.array(nodes);x0=orig.ravel();scale=4
 target=np.array(Image.open('/app/target.png').crop(box).resize(((box[2]-box[0])*scale,(box[3]-box[1])*scale)))[:,:,0]<100
 def unpack(x):
  a=x.reshape(-1,2);return {k:a[ids] for k,ids in indices.items()}
 def fun(x):
  pred=render(unpack(x),scale,box)>127
  err=np.count_nonzero(pred^target)/target.sum()
  # Keep the fit near the smooth pen paths inferred from the photograph.
  reg=.00004*np.sum((x-x0)**2)
  return err+reg
 print(prefix,'initial',fun(x0),flush=True)
 result=minimize(fun,x0,method='Powell',bounds=np.c_[x0-1.6,x0+1.6],options={'maxiter':4,'xtol':.04,'ftol':.0002})
 print(prefix,'final',result.fun,'evals',result.nfev,flush=True)
 for k,v in unpack(result.x).items():base[k]=v.tolist()
 if prefix=='n':
  for name in ['entry','stem','arch']:base['n2_'+name]=(np.array(base['n_'+name])+[184.8,0]).tolist()
 json.dump(base,open(ROOT+'/paths_fit.json','w'))
show(base,'fit')
